import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_D 8
#define TILE_H 4
#define TILE_W 8
#define UNROLL_W 4
#define OC_TILE 8
__global__ void conv3d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int K, int stride, int padding, int dilation, int groups)
{
    int C_in_per_group = C_in / groups;
    int C_out_per_group = C_out / groups;
    int oc_start = blockIdx.y * OC_TILE;
    int n = blockIdx.z;
    int group_id = oc_start / C_out_per_group;
    int ic_start = group_id * C_in_per_group;
    int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    int tiles_h = (H_out + TILE_H - 1) / TILE_H;
    int tile_idx = blockIdx.x;
    int tw = tile_idx % tiles_w;
    int th = (tile_idx / tiles_w) % tiles_h;
    int td = tile_idx / (tiles_w * tiles_h);
    int d_out0 = td * TILE_D;
    int h_out0 = th * TILE_H;
    int w_out0 = tw * TILE_W;
    int tx = threadIdx.x; // width group (each handles UNROLL_W outputs)
    int ty = threadIdx.y; // height
    int tz = threadIdx.z; // depth
    int d_out = d_out0 + tz;
    int h_out = h_out0 + ty;
    int w_out_base = w_out0 + tx * UNROLL_W;
    int ID = (TILE_D - 1) * stride + (K - 1) * dilation + 1;
    int IH = (TILE_H - 1) * stride + (K - 1) * dilation + 1;
    int IW = (TILE_W - 1) * stride + (K - 1) * dilation + 1;
    extern __shared__ float shmem[];
    int weight_size = C_in_per_group * K * K * K;
    float* s_weight = shmem; // OC_TILE * weight_size
    float* s_input = shmem + OC_TILE * weight_size;
    int block_dim_x = TILE_W / UNROLL_W;
    int tid = (tz * TILE_H + ty) * block_dim_x + tx;
    int block_threads = TILE_D * TILE_H * block_dim_x;
    int oc_count = C_out - oc_start;
    if (oc_count > OC_TILE) oc_count = OC_TILE;
    int total_weight_elems = oc_count * weight_size;
    for (int i = tid; i < total_weight_elems; i += block_threads) {
        int oc_local = i / weight_size;
        int w_idx = i % weight_size;
        int oc = oc_start + oc_local;
        s_weight[oc_local * weight_size + w_idx] = weight[(long)oc * weight_size + w_idx];
    }
    int input_tile_size = C_in_per_group * ID * IH * IW;
    int d_in0 = d_out0 * stride - padding;
    int h_in0 = h_out0 * stride - padding;
    int w_in0 = w_out0 * stride - padding;
    for (int i = tid; i < input_tile_size; i += block_threads) {
        int rem = i;
        int iw = rem % IW; rem /= IW;
        int ih = rem % IH; rem /= IH;
        int id = rem % ID; rem /= ID;
        int ic = rem;
        int d_in = d_in0 + id;
        int h_in = h_in0 + ih;
        int w_in = w_in0 + iw;
        float val = 0.0f;
        if (d_in >= 0 && d_in < D_in && h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
            int input_c = ic_start + ic;
            long input_idx = (((long)(n * C_in + input_c) * D_in + d_in) * H_in + h_in) * W_in + w_in;
            val = input[input_idx];
        }
        s_input[i] = val;
    }
    __syncthreads();
    if (d_out < D_out && h_out < H_out) {
        float sum[OC_TILE][UNROLL_W];
        #pragma unroll
        for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
            #pragma unroll
            for (int u = 0; u < UNROLL_W; ++u) sum[oc_local][u] = 0.0f;
        }
        for (int ic = 0; ic < C_in_per_group; ++ic) {
            int ic_base = ic * ID * IH * IW;
            int w_base = ic * K * K * K;
            for (int kd = 0; kd < K; ++kd) {
                int id = tz * stride + kd * dilation;
                for (int kh = 0; kh < K; ++kh) {
                    int ih = ty * stride + kh * dilation;
                    int in_row_base = ic_base + (id * IH + ih) * IW;
                    int w_row_base = w_base + (kd * K + kh) * K;
                    for (int kw = 0; kw < K; ++kw) {
                        float wv[OC_TILE];
                        #pragma unroll
                        for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
                            wv[oc_local] = s_weight[oc_local * weight_size + w_row_base + kw];
                        }
                        #pragma unroll
                        for (int u = 0; u < UNROLL_W; ++u) {
                            int iw = (tx * UNROLL_W + u) * stride + kw * dilation;
                            float in_val = s_input[in_row_base + iw];
                            #pragma unroll
                            for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
                                sum[oc_local][u] += in_val * wv[oc_local];
                            }
                        }
                    }
                }
            }
        }
        #pragma unroll
        for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
            int oc = oc_start + oc_local;
            if (oc < C_out) {
                long out_base_idx = (((long)(n * C_out + oc) * D_out + d_out) * H_out + h_out) * W_out + w_out_base;
                if (w_out_base + UNROLL_W <= W_out && (out_base_idx & 3) == 0) {
                    float4 vals;
                    vals.x = sum[oc_local][0];
                    vals.y = sum[oc_local][1];
                    vals.z = sum[oc_local][2];
                    vals.w = sum[oc_local][3];
                    *reinterpret_cast<float4*>(&output[out_base_idx]) = vals;
                } else {
                    #pragma unroll
                    for (int u = 0; u < UNROLL_W; ++u) {
                        int w_out = w_out_base + u;
                        if (w_out < W_out) {
                            output[out_base_idx + u] = sum[oc_local][u];
                        }
                    }
                }
            }
        }
    }
}
torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);
    int C_out = weight.size(0);
    int K = weight.size(2);
    int D_out = (D_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    int H_out = (H_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    int W_out = (W_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());
    int C_in_per_group = C_in / groups;
    int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    int tiles_h = (H_out + TILE_H - 1) / TILE_H;
    int tiles_d = (D_out + TILE_D - 1) / TILE_D;
    int num_tiles = tiles_w * tiles_h * tiles_d;
    int oc_tiles = (C_out + OC_TILE - 1) / OC_TILE;
    dim3 grid(num_tiles, oc_tiles, N);
    dim3 block(TILE_W / UNROLL_W, TILE_H, TILE_D);
    int ID = (TILE_D - 1) * stride + (K - 1) * dilation + 1;
    int IH = (TILE_H - 1) * stride + (K - 1) * dilation + 1;
    int IW = (TILE_W - 1) * stride + (K - 1) * dilation + 1;
    size_t shmem_size = (size_t)(OC_TILE * C_in_per_group * K * K * K + C_in_per_group * ID * IH * IW) * sizeof(float);
    conv3d_forward_kernel<<<grid, block, shmem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        K, stride, padding, dilation, groups
    );
    return output;
}
"""

conv3d_header = r"""
torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int dilation,
    int groups);
"""

conv3d_module = load_inline(
    name="conv3d_module",
    cpp_sources=conv3d_header,
    cuda_sources=conv3d_source,
    functions=["conv3d_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a standard 3D convolution operation with square input and square kernel,
    using a custom CUDA kernel for the forward pass.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias

        # Weight shape: (out_channels, in_channels // groups, k, k, k)
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, kernel_size)
        )
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
            fan_in = in_channels // groups * kernel_size * kernel_size * kernel_size
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()

        out = conv3d_module.conv3d_forward_cuda(
            x, weight, self.stride, self.padding, self.dilation, self.groups
        )

        if self.use_bias:
            out = out + self.bias.view(1, -1, 1, 1, 1)

        return out


